import type {
  BookingOfferingStatus,
  BookingResourceStatus,
  BookingServiceStatus,
  CommerceParty,
  Package,
  PackageAutomaticItemType,
  PackageDetail,
  PackageItem,
  PackageMember,
  PackageMemberSelf,
  PackageMemberSelfPauseCause,
  PackageMemberStatus,
  PackageMemberRenewal,
  PackageOffering,
  PackageStatus,
  PackageRenewal,
  GetStorefrontPackageParams,
  PackageMinimum,
  PackageStay,
  PackageSummary,
  StorefrontPackage,
  StorefrontPackageItemTerms,
  StorefrontPackageItemTermsType,
  StorefrontPackageOffering,
} from "arky-sdk";
import type * as Public from "arky-sdk/types";
import type { createAdmin } from "arky-sdk/admin";
import type { StorefrontClient } from "arky-sdk/storefront";

type Expect<T extends true> = T;
type Equal<A, B> = (<T>() => T extends A ? 1 : 2) extends <T>() => T extends B ? 1 : 2 ? true : false;
type Missing<T, K extends PropertyKey> = K extends keyof T ? false : true;
type Eshop = ReturnType<typeof createAdmin>["eshop"];

export type MembershipContracts = [
  Expect<Missing<GetStorefrontPackageParams, "subscription_offering_id" | "package_offering_id" | "include_price">>,
  Expect<Equal<PackageStatus["type"], "draft" | "active" | "closed" | "archived" | "deleting">>,
  Expect<Equal<keyof Package, "id" | "store_id" | "key" | "blocks" | "renewal" | "stay" | "minimum" | "schedule" | "status" | "created_at" | "updated_at">>,
  Expect<Equal<Package["renewal"], PackageRenewal>>,
  Expect<Equal<Package["stay"], PackageStay>>,
  Expect<Equal<Package["minimum"], PackageMinimum>>,
  Expect<Equal<PackageDetail["items"], PackageItem[]>>,
  Expect<Equal<keyof PackageSummary, keyof Package | "package_offering_id" | "automatic_item_count" | "market_ids">>,
  Expect<Equal<PackageSummary["market_ids"], string[]>>,
  Expect<Missing<Package, "communication" | "join_policy" | "name" | "title" | "subscription_offering_id">>,
  Expect<Equal<keyof PackageOffering, "id" | "store_id" | "key" | "blocks" | "package_ids" | "created_at" | "updated_at">>,
  Expect<Missing<PackageOffering, "transitions">>,
  Expect<Equal<keyof StorefrontPackageOffering, "id" | "key" | "blocks" | "package_ids">>,
  Expect<Equal<StorefrontPackageOffering["package_ids"], string[]>>,
  Expect<Equal<keyof PackageMember, "id" | "store_id" | "package_id" | "subject" | "renewal" | "status" | "created_at" | "updated_at">>,
  Expect<Equal<PackageMember["subject"], CommerceParty>>,
  Expect<Equal<PackageMember["renewal"], PackageMemberRenewal>>,
  Expect<Equal<PackageMember["status"], PackageMemberStatus>>,
  Expect<Equal<PackageMemberStatus["type"], "awaiting_activation" | "active" | "blocked" | "paused" | "cancelled">>,
  Expect<Equal<PackageMemberRenewal["type"], "never" | "every">>,
  Expect<Missing<PackageMember, "customer_id" | "order_id" | "purchases">>,
  Expect<Equal<keyof PackageMemberSelf, keyof PackageMember>>,
  Expect<Equal<Extract<PackageMemberSelf["status"], { type: "paused" }>["cause"], PackageMemberSelfPauseCause>>,
  Expect<Equal<keyof Eshop["package"], "find" | "findPurchasable" | "get" | "getByKey" | "create" | "update" | "copy" | "delete">>,
  Expect<Equal<keyof Eshop["packageOffering"], "find" | "get" | "getByKey" | "create" | "update" | "delete">>,
  Expect<Missing<Eshop["packageMember"], "add" | "remove" | "delete" | "update">>,
  Expect<Missing<Eshop, "subscription" | "subscriptionPlan" | "subscriptionOffering">>,
  Expect<Missing<StorefrontClient, "packages" | "subscription_plans" | "subscription_offerings">>,
  Expect<Equal<keyof StorefrontClient["eshop"]["package"], "find" | "get" | "getByKey" | "getProductChoices" | "joinFree">>,
  Expect<Equal<StorefrontPackage["package_item_id"], string>>,
  Expect<Equal<StorefrontPackage["package_offering_id"], string | null>>,
  Expect<Missing<StorefrontPackage, "price">>,
  Expect<Equal<keyof StorefrontClient["eshop"]["packageOffering"], "get" | "getByKey">>,
  Expect<Equal<Awaited<ReturnType<StorefrontClient["eshop"]["package"]["get"]>>, StorefrontPackage>>,
  Expect<Equal<Awaited<ReturnType<StorefrontClient["eshop"]["packageOffering"]["get"]>>, StorefrontPackageOffering>>,
  Expect<Equal<StorefrontPackage["items"], StorefrontPackageItemTerms[]>>,
  Expect<Equal<keyof StorefrontPackageItemTerms, "id" | "type">>,
  Expect<Equal<StorefrontPackageItemTerms["type"], StorefrontPackageItemTermsType>>,
  Expect<Missing<StorefrontPackageItemTerms, "allocation_weight">>,
  Expect<Equal<Extract<PackageAutomaticItemType, { type: "rent_product" }>["allocation_weight"], number>>,
  Expect<Equal<Public.StorefrontPackageItemTerms, StorefrontPackageItemTerms>>,
  Expect<Missing<StorefrontPackage, "purchase_allowed">>,
  Expect<Equal<Extract<keyof StorefrontPackage, "status" | "store_id">, never>>,
  Expect<Equal<BookingServiceStatus["type"], "draft" | "active" | "archived" | "deleting">>,
  Expect<Equal<BookingResourceStatus["type"], "draft" | "active" | "archived" | "deleting">>,
  Expect<Equal<BookingOfferingStatus["type"], "draft" | "active" | "archived" | "deleting">>,
];
